63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /**
69	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
70	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
71	     */
72	    /**
73	     * Dedicated audit logger. Successful side-effects (e.g. owner creation) are recorded here so
74	     * they can be routed and asserted independently of the application's diagnostic logging.
75	     */
76	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
77	
78	    private static final Pattern EMAIL_PATTERN =
79	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
80	
81	    /**
82	     * Disposable email domains that are refused: an owner whose email domain is on this blocklist
83	     * is rejected. The value is the already-normalized (trimmed, lower-cased) email's domain.
84	     */
85	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
86	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
87	
88	    /**
89	     * Common address abbreviations expanded to their full form during address normalization.
90	     * Matching is performed per whitespace-separated token on the upper-cased value.
91	     */
92	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
93	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
94	
95	    /**
96	     * Required national-number length (the digits after the country code) per E.164 country code.
97	     * A number whose country code appears here must carry exactly the mapped number of national
98	     * digits; country codes not listed fall back to the generic 8-to-15 total-digit rule.
99	     */
100	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
101	        Map.of("61", 9, "1", 10);
102	
103	    /**
104	     * Inclusive 4-digit postcode range {@code {low, high}} per region, the fixed ground truth for
105	     * validating an owner's postcode against the region derived from its city. A region not listed
106	     * here (e.g. the {@code "UNKNOWN"} locality of an unmapped city) imposes no range constraint, so
107	     * any 4-digit postcode is accepted.
108	     */
109	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
110	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
111	
112	    /**
113	     * City -> canonical region, the fixed ground truth for deriving the region a postcode is
114	     * validated against. A city not listed here derives the {@code "UNKNOWN"} region, which imposes
115	     * no postcode-range constraint.
116	     */
117	    private static final Map<String, String> CITY_REGION = Map.of(
118	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
119	
120	    private final ClinicService clinicService;
121	
122	    private final OwnerMapper ownerMapper;
123	
124	    private final PetMapper petMapper;
125	
126	    private final VisitMapper visitMapper;
