128	    public OwnerRestControllerV1(ClinicService clinicService,
129	                                 OwnerMapper ownerMapper,
130	                                 PetMapper petMapper,
131	                                 VisitMapper visitMapper) {
132	        this.clinicService = clinicService;
133	        this.ownerMapper = ownerMapper;
134	        this.petMapper = petMapper;
135	        this.visitMapper = visitMapper;
136	    }
