138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
141	        Collection<Owner> owners;
142	        if (lastName != null) {
143	            owners = this.clinicService.findOwnerByLastName(lastName);
144	        } else {
145	            owners = this.clinicService.findAllOwners();
146	        }
147	        if (owners.isEmpty()) {
148	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
149	        }
150	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
151	    }
