153	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
154	    @Override
155	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
156	        Owner owner = this.clinicService.findOwnerById(ownerId);
157	        if (owner == null) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
166	        HttpHeaders headers = new HttpHeaders();
167	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
168	        LocalDate suppliedDate = owner.getRegistrationDate();
169	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
170	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
171	        }
172	        LocalDate effectiveDate = suppliedDate != null ? suppliedDate : LocalDate.now();
173	        LocalDate registrationDate = toBusinessDay(effectiveDate);
174	        owner.setRegistrationDate(registrationDate);
175	        long createdToday = this.clinicService.findAllOwners().stream()
176	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
177	            .count();
178	        if (createdToday >= 100) {
179	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
180	        }
181	        owner.setBulkSignupWarning(createdToday > 80);
182	        if (!applyAddress(owner)) {
183	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
184	        }
185	        String telephone = toE164(owner.getTelephone());
186	        if (telephone == null) {
187	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
188	        }
189	        owner.setTelephone(telephone);
190	        if (owner.getEmail() != null) {
191	            String email = normalizeEmail(owner.getEmail());
192	            if (!EMAIL_PATTERN.matcher(email).matches()) {
193	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
194	            }
195	            if (isDisposableEmailDomain(email)) {
196	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
197	            }
198	            owner.setEmail(email);
199	        }
200	        if (!isPostcodeValidForCity(owner.getPostcode(), regionForCity(owner.getCity()))) {
201	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
202	        }
203	        String cityKey = householdKey(owner.getCity());
204	        long cityCount = this.clinicService.findAllOwners().stream()
205	            .filter(existing -> existing.getCity() != null
206	                && cityKey.equals(householdKey(existing.getCity())))
207	            .count();
208	        if (cityCount >= 50) {
209	            return new ResponseEntity<>(HttpStatus.CONFLICT);
210	        }
211	        // The household is keyed on (normalized last name, postcode): every owner derives the same
212	        // deterministic householdId from those two fields, so owners sharing them are the same
213	        // household. This computed id is what duplicate detection and the household size below key off.
214	        String householdId = householdId(owner);
215	        owner.setHouseholdId(householdId);
216	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
217	            .filter(existing -> !existing.getDeleted())
218	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
219	            .toList();
220	        owner.setHouseholdSize(householdMembers.size() + 1);
221	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
222	        // Household-duplicate block: a second owner in an existing household (same computed
223	        // householdId) is rejected as a duplicate. 'sharesHousehold' now only BYPASSES this block —
224	        // declaring the new owner a member — rather than creating the household link itself.
225	        if (!householdMembers.isEmpty() && !sharesHousehold) {
226	            return new ResponseEntity<>(HttpStatus.CONFLICT);
227	        }
228	        // Single consolidated duplicate check: the telephone, email and household duplicate rules are
229	        // all expressed through the one derived identityKey (telephone|email|householdId). A create is
230	        // rejected only when a new owner's WHOLE identityKey equals an existing owner's; because the
231	        // telephone is part of the key, two household members with different telephones are allowed.
232	        // This still catches a full identity repeat even when it declares sharesHousehold.
233	        String identityKey = owner.getIdentityKey();
234	        boolean identityInUse = this.clinicService.findAllOwners().stream()
235	            .filter(existing -> !existing.getDeleted())
236	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
237	        if (identityInUse) {
238	            return new ResponseEntity<>(HttpStatus.CONFLICT);
239	        }
240	        // Soft-duplicate detection. A declared household member (sharesHousehold) is never a suspected
241	        // duplicate. Any other owner sharing an existing owner's last name and postcode with a
242	        // different telephone is now, by definition, a household duplicate already rejected above, so
243	        // it never reaches this point; the check is retained for owners that are not household matches.
244	        if (sharesHousehold) {
245	            owner.setPossibleDuplicate(false);
246	        } else {
247	            String softDuplicateLastNameKey = householdKey(owner.getLastName());
248	            String softDuplicatePostcode = owner.getPostcode();
249	            String softDuplicateTelephone = owner.getTelephone();
250	            Owner possibleDuplicate = softDuplicatePostcode == null ? null
251	                : this.clinicService.findAllOwners().stream()
252	                    .filter(existing -> !existing.getDeleted())
253	                    .filter(existing -> softDuplicateLastNameKey.equals(householdKey(existing.getLastName())))
254	                    .filter(existing -> softDuplicatePostcode.equals(existing.getPostcode()))
255	                    .filter(existing -> !softDuplicateTelephone.equals(existing.getTelephone()))
256	                    .min(Comparator.comparing(Owner::getId))
257	                    .orElse(null);
258	            if (possibleDuplicate != null) {
259	                owner.setPossibleDuplicate(true);
260	                owner.setPossibleDuplicateOf(possibleDuplicate.getId());
261	            } else {
262	                owner.setPossibleDuplicate(false);
263	            }
264	        }
265	        owner.setCustomerCode(customerCode(owner));
266	        String firstNameKey = householdKey(owner.getFirstName());
267	        String namesakeLastNameKey = householdKey(owner.getLastName());
268	        long namesakeCount = this.clinicService.findAllOwners().stream()
269	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
270	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
271	            .count();
272	        owner.setNamesakeCount((int) namesakeCount);
273	        this.clinicService.saveOwner(owner);
274	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
275	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
276	            owner.getMembershipLevel(), owner.getMembershipNumber());
277	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
278	        headers.setLocation(UriComponentsBuilder.newInstance()
279	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
280	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
281	    }
282	
283	    /**
284	     * Validates an owner's postcode against the region derived from its city. The postcode is
285	     * optional: a {@code null} value is always accepted. When present it must fall within the
286	     * inclusive range mapped to the region by {@link #REGION_POSTCODES}; a region with no known
287	     * range (e.g. the {@code "UNKNOWN"} locality of an unmapped city) accepts any 4-digit postcode.
288	     * The 4-digit syntax itself is enforced upstream by bean validation.
289	     *
290	     * @param postcode the owner's postcode (may be {@code null})
291	     * @param locality the region derived from the owner's city
292	     * @return {@code true} when the postcode is absent, the region has no range, or the postcode is
293	     *         within the region's range; {@code false} when it is out of range
294	     */
295	    /**
296	     * The canonical region for the given city via the fixed {@link #CITY_REGION} table, or
297	     * {@code "UNKNOWN"} when the city is {@code null} or not in the table.
298	     *
299	     * @param city the owner's city (may be {@code null})
300	     * @return the canonical region, or {@code "UNKNOWN"}
301	     */
302	    private String regionForCity(String city) {
303	        if (city == null) {
304	            return "UNKNOWN";
305	        }
306	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
307	    }
308	
309	    private boolean isPostcodeValidForCity(String postcode, String locality) {
310	        if (postcode == null) {
311	            return true;
312	        }
313	        int[] range = REGION_POSTCODES.get(locality);
314	        if (range == null) {
315	            return true;
316	        }
317	        int value = Integer.parseInt(postcode);
318	        return value >= range[0] && value <= range[1];
319	    }
320	
321	    /**
322	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
323	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
324	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
325	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. For
326	     * recognised country codes the national number (the digits after the country code) must also be
327	     * exactly the length that country requires ({@code '+61'} needs 9 national digits, {@code '+1'}
328	     * needs 10); a wrong national-number length yields {@code null}.
329	     *
330	     * @param telephone the raw telephone value (may be {@code null})
331	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
332	     *         a valid E.164 number
333	     */
334	    private String toE164(String telephone) {
335	        if (telephone == null) {
336	            return null;
337	        }
338	        String trimmed = telephone.trim();
339	        boolean hasCountryCode = trimmed.startsWith("+");
340	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
341	        if (hasCountryCode) {
342	            cleaned = cleaned.substring(1);
343	        }
344	        if (!cleaned.matches("[0-9]+")) {
345	            return null;
346	        }
347	        String digits;
348	        if (hasCountryCode) {
349	            digits = cleaned;
350	        } else {
351	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
352	            digits = "61" + national;
353	        }
354	        if (digits.length() < 8 || digits.length() > 15) {
355	            return null;
356	        }
357	        if (!hasValidNationalNumberLength(digits)) {
358	            return null;
359	        }
360	        return "+" + digits;
361	    }
362	
363	    /**
364	     * Checks the national-number length of an E.164 digit string (country code plus national
365	     * number, without the leading {@code '+'}) against its country code. When the number's country
366	     * code is one of the {@link #NATIONAL_NUMBER_LENGTHS recognised codes}, the digits after the
367	     * country code must number exactly what that country requires; the longest matching country
368	     * code wins. Numbers whose country code is not recognised are accepted here (they are governed
369	     * only by the generic total-length rule).
370	     *
371	     * @param digits the E.164 digits without the leading {@code '+'} (e.g. {@code "61412345678"})
372	     * @return {@code true} if the national-number length is acceptable for the country code
373	     */
374	    private boolean hasValidNationalNumberLength(String digits) {
375	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
376	            .filter(entry -> digits.startsWith(entry.getKey()))
377	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
378	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
379	            .orElse(true);
380	    }
381	
382	    /**
383	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
384	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
385	     *
386	     * @param email the raw email value (must not be {@code null})
387	     * @return the trimmed, lower-cased email
388	     */
389	    private String normalizeEmail(String email) {
390	        return email.trim().toLowerCase(Locale.ROOT);
391	    }
392	
393	    /**
394	     * Whether the domain of the given normalized email is on the disposable-domain blocklist
395	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The domain is the substring after the last {@code '@'};
396	     * an email without an {@code '@'} carries no blocked domain.
397	     *
398	     * @param email the trimmed, lower-cased email
399	     * @return {@code true} when the email's domain is blocklisted
400	     */
401	    private boolean isDisposableEmailDomain(String email) {
402	        int at = email.lastIndexOf('@');
403	        if (at < 0) {
404	            return false;
405	        }
406	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
407	    }
408	
409	    /**
410	     * Applies the owner's address, preferring the structured form over the flat one. When a
411	     * non-blank {@code addressLine1} is supplied the structured fields are normalized in place and
412	     * the flat {@code address} is composed as the normalized {@code addressLine1} followed, when a
413	     * non-blank {@code addressLine2} is present, by a single space and the normalized
414	     * {@code addressLine2}. Otherwise the flat {@code address} is normalized in place. An owner
415	     * that supplies neither a non-blank {@code addressLine1} nor a non-blank flat {@code address}
416	     * is invalid.
417	     *
418	     * @param owner the owner whose address fields are normalized and composed in place
419	     * @return {@code true} when a usable address was applied, {@code false} when none was supplied
420	     */
421	    private boolean applyAddress(Owner owner) {
422	        String line1 = owner.getAddressLine1();
423	        if (line1 != null && !line1.isBlank()) {
424	            String normalizedLine1 = normalizeAddress(line1);
425	            owner.setAddressLine1(normalizedLine1);
426	            String composed = normalizedLine1;
427	            String line2 = owner.getAddressLine2();
428	            if (line2 != null && !line2.isBlank()) {
429	                String normalizedLine2 = normalizeAddress(line2);
430	                owner.setAddressLine2(normalizedLine2);
431	                composed = normalizedLine1 + " " + normalizedLine2;
432	            }
433	            owner.setAddress(composed);
434	            return true;
435	        }
436	        String address = normalizeAddress(owner.getAddress());
437	        if (address == null || address.isEmpty()) {
438	            return false;
439	        }
440	        owner.setAddress(address);
441	        return true;
442	    }
443	
444	    /**
445	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
446	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
447	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
448	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
449	     * normalized form, and every household comparison uses it.
450	     *
451	     * @param address the raw address value (may be {@code null})
452	     * @return the normalized address, or {@code null} if the input was {@code null}
453	     */
454	    private String normalizeAddress(String address) {
455	        if (address == null) {
456	            return null;
457	        }
458	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
459	        if (collapsed.isEmpty()) {
460	            return collapsed;
461	        }
462	        String[] tokens = collapsed.split(" ");
463	        StringBuilder sb = new StringBuilder(collapsed.length());
464	        for (int i = 0; i < tokens.length; i++) {
465	            if (i > 0) {
466	                sb.append(' ');
467	            }
468	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
469	        }
470	        return sb.toString();
471	    }
472	
473	    /**
474	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
475	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
476	     * so that owners are compared case-insensitively with collapsed whitespace.
477	     *
478	     * @param value the raw value (must not be {@code null})
479	     * @return the normalized comparison key
480	     */
481	    private String householdKey(String value) {
482	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
483	    }
484	
485	    /**
486	     * Derives a stable, shared household identifier for the owner's household: the first 12 hex
487	     * characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}, where the
488	     * last name is normalized with {@link #householdKey} and an absent postcode is rendered as the
489	     * empty string. Because it is a pure function of the last name and postcode, every owner sharing
490	     * those two fields derives the identical identifier and therefore belongs to the same household.
491	     *
492	     * @param owner the owner whose household identifier is derived
493	     * @return the stable household identifier
494	     */
495	    private String householdId(Owner owner) {
496	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
497	        String key = householdKey(owner.getLastName()) + "|" + postcode;
498	        try {
499	            byte[] digest = MessageDigest.getInstance("SHA-256")
500	                .digest(key.getBytes(StandardCharsets.UTF_8));
501	            StringBuilder sb = new StringBuilder(digest.length * 2);
502	            for (byte b : digest) {
503	                sb.append(String.format("%02x", b));
504	            }
505	            return sb.substring(0, 12);
506	        }
507	        catch (java.security.NoSuchAlgorithmException e) {
508	            throw new IllegalStateException("SHA-256 not available", e);
509	        }
510	    }
511	
512	    /**
513	     * Builds the customer code for a newly registered owner in the form
514	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the region code derived from the owner's
515	     * postcode (the same region derivation shared with {@link Owner#getLocality() locality}:
516	     * postcode range first, falling back to the city, or {@code 'UNKNOWN'}) and {@code HASH8} is the
517	     * first 8 upper-case hex characters of the SHA-256 digest of the normalized telephone
518	     * concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). When the computed code
519	     * collides with an existing owner's customer code, {@code '-<n>'} is appended using the
520	     * smallest {@code n} of 2 or more that makes the result unique, guaranteeing distinct owners
521	     * always receive distinct customer codes.
522	     *
523	     * @param owner the owner whose customer code is derived (with normalized telephone already set)
524	     * @return the assigned customer code
525	     */
526	    private String customerCode(Owner owner) {
527	        String region = owner.getLocality();
528	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName(), 8);
529	        String base = region + "-" + hash8;
530	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
531	            .map(Owner::getCustomerCode)
532	            .filter(code -> code != null)
533	            .collect(Collectors.toSet());
534	        if (!existingCodes.contains(base)) {
535	            return base;
536	        }
537	        int n = 2;
538	        while (existingCodes.contains(base + "-" + n)) {
539	            n++;
540	        }
541	        return base + "-" + n;
542	    }
543	
544	    /**
545	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
546	     * UTF-8 bytes of {@code input}.
547	     *
548	     * @param input  the value to hash
549	     * @param length the number of leading hex characters to keep
550	     * @return the truncated, upper-cased hex digest
551	     */
552	    private String sha256UpperHex(String input, int length) {
553	        try {
554	            byte[] digest = MessageDigest.getInstance("SHA-256")
555	                .digest(input.getBytes(StandardCharsets.UTF_8));
556	            StringBuilder sb = new StringBuilder(digest.length * 2);
557	            for (byte b : digest) {
558	                sb.append(String.format("%02x", b));
559	            }
560	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
561	        }
562	        catch (java.security.NoSuchAlgorithmException e) {
563	            throw new IllegalStateException("SHA-256 not available", e);
564	        }
565	    }
566	
567	    /** Fixed public holidays that the business-day roll skips. */
568	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
569	        LocalDate.parse("2026-01-01"),
570	        LocalDate.parse("2026-01-26"),
571	        LocalDate.parse("2026-04-25"),
572	        LocalDate.parse("2026-12-25"),
573	        LocalDate.parse("2026-12-28"));
574	
575	    /**
576	     * Rolls a registration date forward onto a business day. When the given date falls on a
577	     * Saturday, Sunday or a listed public holiday it is advanced one day at a time until it
578	     * lands on a non-holiday weekday; a business day is returned unchanged.
579	     *
580	     * @param date the effective registration date (must not be {@code null})
581	     * @return the same date if it is already a business day, otherwise the next business day
582	     */
583	    private LocalDate toBusinessDay(LocalDate date) {
584	        while (isNonBusinessDay(date)) {
585	            date = date.plusDays(1);
586	        }
587	        return date;
588	    }
589	
590	    private boolean isNonBusinessDay(LocalDate date) {
591	        DayOfWeek dayOfWeek = date.getDayOfWeek();
592	        return dayOfWeek == DayOfWeek.SATURDAY
593	            || dayOfWeek == DayOfWeek.SUNDAY
594	            || PUBLIC_HOLIDAYS.contains(date);
595	    }
596	
597	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
598	    @Override
599	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
600	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
601	        if (currentOwner == null) {
602	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
603	        }
604	        String email = ownerFieldsDto.getEmail();
605	        if (email != null) {
606	            email = normalizeEmail(email);
607	            if (!EMAIL_PATTERN.matcher(email).matches()) {
608	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
609	            }
610	        }
611	        String telephone = toE164(ownerFieldsDto.getTelephone());
612	        if (telephone == null) {
613	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
614	        }
615	        currentOwner.setAddress(ownerFieldsDto.getAddress());
616	        currentOwner.setCity(ownerFieldsDto.getCity());
617	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
618	        currentOwner.setLastName(ownerFieldsDto.getLastName());
619	        currentOwner.setTelephone(telephone);
620	        currentOwner.setEmail(email);
621	        this.clinicService.saveOwner(currentOwner);
622	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
623	    }
624	
625	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
626	    @Transactional
627	    @Override
628	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
629	        Owner owner = this.clinicService.findOwnerById(ownerId);
630	        if (owner == null) {
631	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
632	        }
633	        // Soft-delete: flag the owner deleted and retain the record so it can still be read back.
634	        owner.setDeleted(true);
635	        this.clinicService.saveOwner(owner);
636	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
637	    }
638	
639	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
640	    @Override
641	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
642	        Owner owner = this.clinicService.findOwnerById(ownerId);
643	        if (owner == null) {
644	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
645	        }
646	        HttpHeaders headers = new HttpHeaders();
647	        Pet pet = petMapper.toPet(petFieldsDto);
648	        owner.setId(ownerId);
649	        pet.setOwner(owner);
650	        pet.getType().setName(null);
651	        this.clinicService.savePet(pet);
652	        PetDto petDto = petMapper.toPetDto(pet);
653	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
654	            .buildAndExpand(pet.getId()).toUri());
655	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
656	    }
657	
658	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
659	    @Override
660	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
661	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
662	        if (currentOwner != null) {
663	            Pet currentPet = this.clinicService.findPetById(petId);
664	            if (currentPet != null) {
665	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
666	                currentPet.setName(petFieldsDto.getName());
667	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
668	                this.clinicService.savePet(currentPet);
669	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
670	            }
671	        }
672	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
673	    }
674	
