676	    @Override
677	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
678	        HttpHeaders headers = new HttpHeaders();
679	        Visit visit = visitMapper.toVisit(visitFieldsDto);
680	        Pet pet = new Pet();
681	        pet.setId(petId);
682	        visit.setPet(pet);
