160	    /**
161	     * The stored E.164 {@link #telephone} formatted for humans as the country code, a single
162	     * space, then the national digits (the digits after the country code) grouped in threes from
163	     * the left, e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}. The country code is
164	     * a single digit for the {@code +1} and {@code +7} zones and two digits otherwise.
165	     *
166	     * @return the human-formatted telephone, or the raw {@link #telephone} unchanged when it is
167	     *         {@code null} or not a {@code +} followed by digits
168	     */
169	    public String getTelephoneDisplay() {
170	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
171	            return this.telephone;
172	        }
173	        String digits = this.telephone.substring(1);
174	        int countryCodeLength = ONE_DIGIT_CALLING_CODES.contains(digits.substring(0, 1)) ? 1 : 2;
175	        if (digits.length() <= countryCodeLength) {
176	            return this.telephone;
177	        }
178	        String countryCode = digits.substring(0, countryCodeLength);
179	        String national = digits.substring(countryCodeLength);
180	        StringBuilder grouped = new StringBuilder();
181	        for (int i = 0; i < national.length(); i++) {
182	            if (i > 0 && i % 3 == 0) {
183	                grouped.append(' ');
184	            }
185	            grouped.append(national.charAt(i));
186	        }
187	        return "+" + countryCode + " " + grouped;
188	    }
