373	     *
374	     * @return the formatted membership number, or {@code null} if the customer code or
375	     *         registration date has not been assigned
376	     */
377	    public String getMembershipNumber() {
378	        if (this.customerCode == null || this.registrationDate == null) {
379	            return null;
380	        }
381	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
382	    }
383	
384	    /**
385	     * The owner's Luhn check digit: a single digit ({@code 0}-{@code 9}) computed with the
386	     * standard Luhn algorithm over the decimal digits contained in the {@code customerCode}
387	     * (non-digit characters are ignored).
388	     *
389	     * @return the Luhn check digit, or {@code null} if the customer code has not been assigned
390	     */
391	    public Integer getCheckDigit() {
392	        if (this.customerCode == null) {
393	            return null;
394	        }
395	        int sum = 0;
396	        boolean dbl = true;
397	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
398	            char c = this.customerCode.charAt(i);
399	            if (c < '0' || c > '9') {
400	                continue;
401	            }
402	            int d = c - '0';
403	            if (dbl) {
404	                d *= 2;
405	                if (d > 9) {
406	                    d -= 9;
407	                }
408	            }
409	            sum += d;
410	            dbl = !dbl;
411	        }
412	        return (10 - (sum % 10)) % 10;
413	    }
414	
415	    /**
416	     * The owner's membership points, starting at {@code 0}. The owner gains {@code 2} when
417	     * they carry an email address, {@code 1} when they have no namesakes
418	     * ({@code namesakeCount} is {@code 0}), {@code 2} for a household of {@code 3} or more
419	     * members ({@code householdSize}), and {@code 3} for tenure of more than {@code 365}
420	     * days (measured from the {@code registrationDate}). Because a newly created owner has
421	     * zero tenure, a new owner can score at most {@code 5} points.
422	     *
423	     * @return the membership points
424	     */
425	    public Integer getMembershipPoints() {
426	        int points = 0;
427	        boolean hasEmail = this.email != null && !this.email.isBlank();
428	        if (hasEmail) {
429	            points += 2;
430	        }
431	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
432	        if (noNamesakes) {
433	            points += 1;
434	        }
435	        if (this.householdSize != null && this.householdSize >= 3) {
436	            points += 2;
437	        }
438	        if (this.registrationDate != null
439	            && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
440	            points += 3;
441	        }
442	        return points;
443	    }
444	
445	    /**
446	     * The owner's numeric membership level, from {@code 1} to {@code 4}, derived from the
447	     * {@link #getMembershipPoints() membership points}: {@code 1} for {@code 0-1} points,
448	     * {@code 2} for {@code 2-3} points, {@code 3} for {@code 4-5} points, and {@code 4} for
449	     * {@code 6} or more points. Because a newly created owner has zero tenure, a new owner
450	     * scores at most {@code 5} points and so never exceeds level {@code 3}; level {@code 4}
451	     * is reserved for owners whose tenure exceeds {@code 365} days.
452	     *
453	     * @return the membership level
454	     */
455	    public Integer getMembershipLevel() {
456	        int points = getMembershipPoints();
457	        if (points >= 6) {
458	            return 4;
459	        }
460	        if (points >= 4) {
461	            return 3;
462	        }
463	        if (points >= 2) {
464	            return 2;
465	        }
466	        return 1;
467	    }
468	
469	    /**
470	     * The owner's preferred contact channel: {@code "EMAIL"} when the owner carries an
471	     * email address, otherwise {@code "PHONE"}.
472	     *
473	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
474	     */
475	    public String getContactPreference() {
476	        boolean hasEmail = this.email != null && !this.email.isBlank();
477	        return hasEmail ? "EMAIL" : "PHONE";
478	    }
479	
480	    /**
481	     * The owner's identity key: the single derived value used for duplicate detection, formed as
482	     * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}. The telephone and
483	     * email are the already-normalized stored values and a {@code null} email or household id is
484	     * rendered as the empty string. Two owners are duplicates only when their whole identity keys
485	     * are equal; because the telephone is part of the key, household members with different
486	     * telephones have different identity keys.
487	     *
488	     * @return the derived identity key
489	     */
490	    public String getIdentityKey() {
491	        String telephonePart = this.telephone == null ? "" : this.telephone;
492	        String emailPart = this.email == null ? "" : this.email;
493	        String householdPart = this.householdId == null ? "" : this.householdId;
494	        return telephonePart + "|" + emailPart + "|" + householdPart;
495	    }
496	
497	    /**
498	     * City -> canonical region, the fixed ground truth for deriving locality.
499	     */
500	    private static final Map<String, String> CITY_REGION = Map.of(
501	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
502	
503	    /**
504	     * Region -> inclusive 4-digit postcode range {@code {low, high}}, the fixed ground truth for
505	     * deriving locality from the postcode ahead of the city.
506	     */
507	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
508	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
509	
510	    /**
511	     * The owner's locality: the canonical region resolved by the postcode range first
512	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), falling back to the
513	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
514	     * {@code Brisbane->QLD}) when the postcode is absent or in no known range, or {@code "UNKNOWN"}
515	     * when the city is not in the table either. The postcode takes precedence so cities that share a
516	     * name are disambiguated by their postcode's region.
517	     *
518	     * @return the canonical region string, or {@code "UNKNOWN"}
519	     */
520	    public String getLocality() {
521	        String byPostcode = regionForPostcode(this.postcode);
522	        if (byPostcode != null) {
523	            return byPostcode;
524	        }
525	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
526	    }
527	
528	    /**
529	     * Region -> IANA timezone name, the fixed ground truth for deriving the owner's timezone from
530	     * its locality.
531	     */
532	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
533	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
534	
535	    /**
536	     * The owner's timezone: the IANA name resolved from the {@link #getLocality() locality} via the
537	     * fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
538	     * {@code QLD->Australia/Brisbane}), or {@code null} when the locality is not one of these regions
539	     * (e.g. {@code "UNKNOWN"}).
540	     *
541	     * @return the IANA timezone name, or {@code null}
542	     */
543	    public String getTimezone() {
544	        return REGION_TIMEZONE.get(getLocality());
545	    }
546	
547	    /**
548	     * Region whose postcode range contains the given postcode, or {@code null} when the postcode is
549	     * absent, not a 4-digit number, or in no known range.
550	     *
551	     * @param postcode the owner's postcode (may be {@code null})
552	     * @return the matching region, or {@code null}
553	     */
554	    private static String regionForPostcode(String postcode) {
555	        if (postcode == null || !postcode.matches("\\d{4}")) {
556	            return null;
557	        }
558	        int value = Integer.parseInt(postcode);
559	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
560	            int[] range = entry.getValue();
561	            if (value >= range[0] && value <= range[1]) {
562	                return entry.getKey();
563	            }
564	        }
565	        return null;
566	    }
567	
568	    protected Set<Pet> getPetsInternal() {
569	        if (this.pets == null) {
570	            this.pets = new HashSet<>();
571	        }
572	        return this.pets;
573	    }
574	
575	    protected void setPetsInternal(Set<Pet> pets) {
576	        this.pets = pets;
577	    }
578	
579	    public List<Pet> getPets() {
580	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
581	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
582	        return Collections.unmodifiableList(sortedPets);
583	    }
584	
585	    public void setPets(List<Pet> pets) {
586	        this.pets = new HashSet<>(pets);
587	    }
588	
589	    public void addPet(Pet pet) {
590	        getPetsInternal().add(pet);
591	        pet.setOwner(this);
592	    }
593	
594	    /**
595	     * Return the Pet with the given name, or null if none found for this Owner.
596	     *
597	     * @param name to test
598	     * @return true if pet name is already in use
599	     */
600	    public Pet getPet(String name) {
601	        return getPet(name, false);
602	    }
603	
604	    /**
605	     * Return the Pet with the given name, or null if none found for this Owner.
606	     *
607	     * @param name to test
608	     * @return true if pet name is already in use
609	     */
610	    public Pet getPet(String name, boolean ignoreNew) {
611	        name = name.toLowerCase();
612	        for (Pet pet : getPetsInternal()) {
613	            if (!ignoreNew || !pet.isNew()) {
614	                String compName = pet.getName();
615	                compName = compName.toLowerCase();
616	                if (compName.equals(name)) {
617	                    return pet;
618	                }
619	            }
620	        }
621	        return null;
622	    }
623	
624	    public Pet getPet(Integer petId) {
625	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
626	    }
627	
628	    @Override
629	    public String toString() {
630	        return new ToStringCreator(this)
631	
632	            .append("id", this.getId())
633	            .append("new", this.isNew())
634	            .append("lastName", this.getLastName())
635	            .append("firstName", this.getFirstName())
636	            .append("address", this.address)
637	            .append("city", this.city)
638	            .append("telephone", this.telephone)
639	            .append("email", this.email)
640	            .toString();
641	    }
642	}
